import XCTest

final class TapOpenTests: XCTestCase {
    func testOpenCaturday() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 15) {
            openButton.tap()
            Thread.sleep(forTimeInterval: 4)
            return
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        Thread.sleep(forTimeInterval: 2)

        let searchTab = app.tabBars.buttons["Search"]
        if searchTab.waitForExistence(timeout: 10) {
            searchTab.tap()
        } else {
            app.buttons["Search"].firstMatch.tap()
        }
        Thread.sleep(forTimeInterval: 2)

        let field = app.textFields.firstMatch
        XCTAssertTrue(field.waitForExistence(timeout: 10), "search field not found")
        field.tap()
        field.typeText("caturday")
        Thread.sleep(forTimeInterval: 3)

        let tag = app.staticTexts["#caturday"].firstMatch
        XCTAssertTrue(tag.waitForExistence(timeout: 15), "#caturday result not found")
        tag.tap()
        Thread.sleep(forTimeInterval: 3)
    }
}

